					{value.length > 0 ? `${value.length} selected` : 'All'}
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent className='max-h-64 min-w-48'>
				{options.map((option) => (
					<DropdownMenuCheckboxItem
